def test_recursive_exception_group():
    try:
        # Create a recursive exception group
        # We can create a custom class that inherits from BaseExceptionGroup and overrides the exceptions property.

        class RecursiveGroup(ExceptionGroup):
            def __init__(self, *args, **kwargs):
                super().__init__(*args, **kwargs)
                self.exceptions = (self,) # Circular reference!

        try:
            raise RecursiveGroup("circular")
